  const [conversationSummary, setConversationSummary] = useState<ConversationSummary>();
  const [knowledgeDocuments, setKnowledgeDocuments] = useState<KnowledgeDocument[]>([]);
  const [knowledgePath, setKnowledgePath] = useState("");
  const [knowledgeQuery, setKnowledgeQuery] = useState("");
  const [knowledgeResults, setKnowledgeResults] = useState<KnowledgeChunk[]>([]);
  const [knowledgeStatus, setKnowledgeStatus] = useState("");
  const [mcpServers, setMcpServers] = useState<McpServerProfile[]>([]);
  const [selectedMcp, setSelectedMcp] = useState<McpServerProfile>();
  const [mcpTools, setMcpTools] = useState<McpToolInfo[]>([]);
  const [mcpStatus, setMcpStatus] = useState("");
  const [mcpForm, setMcpForm] = useState({ name: "", command: "", args: "" });
  const [plugins, setPlugins] = useState<PluginProfile[]>([]);
  const [selectedPlugin, setSelectedPlugin] = useState<PluginProfile>();
  const [pluginTools, setPluginTools] = useState<PluginToolInfo[]>([]);
  const [pluginPath, setPluginPath] = useState("");
  const [pluginStatus, setPluginStatus] = useState("");
  const [themeMode, setThemeMode] = useState<ThemeMode>(() => (localStorage.getItem("xpaw-theme-mode") as ThemeMode) || "system");
  const [accent, setAccent] = useState(() => localStorage.getItem("xpaw-theme-accent") || "#b7d956");
  const [modeProfiles, setModeProfiles] = useState<{ conversation?: string; roleplay?: string; task?: string }>({});
  const [capabilities, setCapabilities] = useState<ModelCapabilities>({ thinking: false, tools: true, roleplay: "experimental", contextWindow: 4096 });
  const [characterCards, setCharacterCards] = useState<StoredCharacterCard[]>([]);
  const [characterPath, setCharacterPath] = useState("");
  const [cardStatus, setCardStatus] = useState("");
  const [worldBooks, setWorldBooks] = useState<WorldBook[]>([]);
  const [worldDraft, setWorldDraft] = useState({ name: "", description: "", entries: [] as WorldBookEntry[] });
  const [worldEntryDraft, setWorldEntryDraft] = useState({ title: "", keywords: "", content: "", priority: 10 });
  const [dataPath, setDataPath] = useState("");
