  const saveCheckpoint = async () => { if (!companion.sceneTitle || !companion.sceneSummary) return; await window.xpaw.addSceneCheckpoint(companion.sceneTitle, companion.sceneSummary); await refreshCompanion(); };
  if (view === "companion") return <main className="app-shell"><aside className="rail"><div className="mark">🐾</div><button className="rail-button" onClick={() => setView("chat")}>✉</button><button className="rail-button active">🐾</button><button className="rail-button" onClick={() => setView("character")}>☷</button><button className="rail-button" onClick={() => setView("settings")}>⚙</button></aside><aside className="sidebar"><div className="brand"><span>{character?.name || "XPaw"}</span><small>COMPANION LAYER</small></div><div className="character"><div className="avatar paw-avatar">🐾</div><div><strong>{companion.relationshipLabel}</strong><small>{companion.sceneTitle || "尚未设置场景"}</small></div><i></i></div><p className="settings-note">场景是虚构上下文，不会成为用户真实记忆，也不会自动触发现实工具。</p></aside><section className="settings-page"><header><div><p className="eyebrow">角色陪伴</p><h1>关系与场景</h1></div><button className="back" onClick={() => setView("chat")}>返回对话</button></header><div className="companion-layout"><div className="settings-form"><label>关系标签<input value={companion.relationshipLabel} onChange={(event) => setCompanion({ ...companion, relationshipLabel: event.target.value })} placeholder="例如：朋友、搭档、自定义" /></label><label>互动边界<textarea value={companion.boundaries} onChange={(event) => setCompanion({ ...companion, boundaries: event.target.value })} placeholder="例如：希望保持轻松、避免过度亲密描写。" /></label><label>场景标题<input value={companion.sceneTitle} onChange={(event) => setCompanion({ ...companion, sceneTitle: event.target.value })} placeholder="例如：雨夜咖啡馆" /></label><label>场景地点/设定<textarea value={companion.sceneSetting} onChange={(event) => setCompanion({ ...companion, sceneSetting: event.target.value })} placeholder="描述地点、时间和氛围。" /></label><label>场景摘要<textarea value={companion.sceneSummary} onChange={(event) => setCompanion({ ...companion, sceneSummary: event.target.value })} placeholder="记录当前虚构剧情进展。" /></label><div className="companion-actions"><button className="save" onClick={() => void window.xpaw.saveCompanionState(companion)}>保存陪伴状态</button><button onClick={() => void saveCheckpoint()}>保存场景检查点</button></div></div><div className="checkpoint-list"><h2>场景检查点</h2>{checkpoints.map((checkpoint) => <article key={checkpoint.id}><strong>{checkpoint.title}</strong><p>{checkpoint.summary}</p><small>{checkpoint.createdAt}</small><button onClick={() => void window.xpaw.deleteSceneCheckpoint(checkpoint.id).then(refreshCompanion)}>删除</button></article>)}</div></div></section><aside className="insights"><p className="eyebrow">模式说明</p><h2>角色扮演</h2><div className="workspace"><small>只使用虚构场景上下文</small><small>不向模型提供现实工具</small><small>需要真实操作时切换到任务模式</small></div></aside></main>;
  const newConversation = async () => { if (busy) return; const result = await window.xpaw.newConversation(); setActiveConversation(result.conversationId); setActivity(undefined); setMessages([{ role: "assistant", content: "新的对话已开始。" }]); await refresh(); };
